select coalesce(t1_0.from_account_id,t1_0.to_account_id),sum(t1_0.amount) from transactions t1_0 where t1_0.transaction_type in ('DEPOSIT','WITHDRAWAL') and t1_0.status='COMPLETED' and t1_0.processed_at>='2026-09-28 00:00:00+00' and t1_0.processed_at<'2026-09-29 00:00:00+00' group by coalesce(t1_0.from_account_id,t1_0.to_account_id)
select t1_0.transaction_id,t1_0.amount,t1_0.created_at,t1_0.from_account_id,t1_0.idempotency_key,t1_0.memo,t1_0.processed_at,t1_0.status,t1_0.to_account_id,t1_0.transaction_type from transactions t1_0 where t1_0.transaction_type='TRANSFER' and t1_0.status='COMPLETED' and t1_0.processed_at between '2026-09-27 15:00:00+00' and '2026-09-28 15:00:00+00' order by t1_0.from_account_id,t1_0.processed_at
select a1_0.account_id,a1_0.account_number,a1_0.account_type,a1_0.closed_at,a1_0.created_at,a1_0.current_balance_cache,a1_0.customer_id,a1_0.hold_amount,a1_0.opened_at,a1_0.status,a1_0.updated_at from accounts a1_0
